arch-02.solution:
package main

import "errors"

var ErrNoQuorum = errors.New("not enough replicas")

type Replica struct {
	Alive   bool
	Version int
	Value   string
}

func Overlaps(n, w, r int) bool {
	return w+r > n
}

func Write(rs []*Replica, w int, version int, value string) error {
	ok := 0
	for _, r := range rs {
		if r.Alive {
			r.Version, r.Value = version, value
			ok++
		}
	}
	if ok < w {
		return ErrNoQuorum
	}
	return nil
}

func Read(rs []*Replica, r int) (string, error) {
	var best *Replica
	read := 0
	for _, rep := range rs {
		if read == r {
			break
		}
		if !rep.Alive {
			continue
		}
		read++
		if best == nil || rep.Version > best.Version {
			best = rep
		}
	}
	if read < r {
		return "", ErrNoQuorum
	}
	return best.Value, nil
}

