arch-03.solution:
package main

import (
	"slices"
	"time"
)

type Registry struct {
	now       func() time.Time
	ttl       time.Duration
	instances map[string]map[string]time.Time
}

func NewRegistry(now func() time.Time, ttl time.Duration) *Registry {
	return &Registry{now: now, ttl: ttl, instances: map[string]map[string]time.Time{}}
}

func (r *Registry) Register(service, addr string) {
	m, ok := r.instances[service]
	if !ok {
		m = map[string]time.Time{}
		r.instances[service] = m
	}
	m[addr] = r.now()
}

func (r *Registry) Deregister(service, addr string) {
	delete(r.instances[service], addr)
}

func (r *Registry) Instances(service string) []string {
	var out []string
	now := r.now()
	for addr, last := range r.instances[service] {
		if now.Sub(last) > r.ttl {
			delete(r.instances[service], addr)
			continue
		}
		out = append(out, addr)
	}
	slices.Sort(out)
	return out
}

