	r := NewRegistry(func() time.Time { return now }, 10*time.Second)
	r.Register("order", "10.0.0.2:9000")
	r.Register("order", "10.0.0.1:9000")
	r.Register("user", "10.0.1.1:9000")
	if got := r.Instances("order"); !slices.Equal(got, []string{"10.0.0.1:9000", "10.0.0.2:9000"}) {
		t.Fatalf("Instances = %v", got)
