	r.Register("order", "10.0.0.1:9000") // 心跳
	now = now.Add(5 * time.Second)
	if got := r.Instances("order"); !slices.Equal(got, []string{"10.0.0.1:9000"}) {
		t.Fatalf("没有心跳的实例应下线：%v", got)
	}
	r.Deregister("order", "10.0.0.1:9000")
	if got := r.Instances("order"); len(got) != 0 {
		t.Fatalf("注销后应为空：%v", got)
	}
	if got := r.Instances("unknown"); len(got) != 0 {
		t.Fatal("不存在的服务返回空")
	}
}

