package main

type node struct {
	name    string
	weight  int
	current int
}

type SWRR struct {
	nodes []*node
}

func (s *SWRR) Add(name string, weight int) {
	s.nodes = append(s.nodes, &node{name: name, weight: weight})
}

func (s *SWRR) Next() string {
	total := 0
	var best *node
	for _, n := range s.nodes {
		n.current += n.weight
		total += n.weight
		if best == nil || n.current > best.current {
			best = n
		}
	}
	if best == nil {
		return ""
	}
	best.current -= total
	return best.name
}

