arch-04.solution:
package main

type Node struct {
	Name     string
	Inflight int
}

func PickP2C(nodes []*Node, randIntn func(int) int) *Node {
	if len(nodes) == 1 {
		return nodes[0]
	}
	i := randIntn(len(nodes))
	j := randIntn(len(nodes) - 1)
	if j >= i {
		j++ // 保证 j != i
	}
	a, b := nodes[i], nodes[j]
	if b.Inflight < a.Inflight {
		return b
	}
	return a
}

