package main

type Message struct {
	ID       int
	Payload  string
	Sent     bool
	Attempts int
}

type Outbox struct {
	Msgs []*Message // 按 ID 升序
}

func (o *Outbox) Relay(publish func(Message) error) int {
	n := 0
	for _, m := range o.Msgs {
		if m.Sent {
			continue
		}
		if err := publish(*m); err != nil {
			m.Attempts++
			continue
		}
		m.Sent = true
		n++
	}
	return n
}

