package main

import (
	"errors"
	"slices"
	"testing"
)

func TestRelay(t *testing.T) {
	o := &Outbox{Msgs: []*Message{{ID: 1, Payload: "a"}, {ID: 2, Payload: "b"}, {ID: 3, Payload: "c"}}}
	var delivered []int
	mqDown := true
	publish := func(m Message) error {
		if m.ID == 2 && mqDown {
			return errors.New("broker unavailable")
		}
		delivered = append(delivered, m.ID)
		return nil
	}
	if n := o.Relay(publish); n != 2 {
		t.Fatalf("第一次投递成功 %d 条，期望 2", n)
	}
	if o.Msgs[1].Sent || o.Msgs[1].Attempts != 1 {
		t.Fatalf("失败的消息应保留并记录尝试次数：%+v", *o.Msgs[1])
	}
	mqDown = false
	if n := o.Relay(publish); n != 1 {
		t.Fatalf("第二次只需要投递剩下的 1 条，实际 %d", n)
	}
	if !slices.Equal(delivered, []int{1, 3, 2}) {
		t.Fatalf("投递记录 = %v", delivered)
	}
	if n := o.Relay(publish); n != 0 {
		t.Fatal("已发送的消息不应重复投递")
	}
}

