		wg.Add(1)
		go func() {
			defer wg.Done()
			var last int64
			for i := 0; i < 5000; i++ {
				id, err := s.Next()
				if err != nil || id <= last {
					t.Errorf("id=%d last=%d err=%v：同一个调用方拿到的 ID 应递增", id, last, err)
					return
				}
				last = id
				mu.Lock()
				seen[id] = true
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if len(seen) != 20000 {
		t.Fatalf("应生成 20000 个不重复的 ID，实际 %d 个", len(seen))
	}
}

func TestLayout(t *testing.T) {
	base := epoch + 1000
	s, _ := New(513, func() int64 { return base })
	s.Next()
	id, _ := s.Next()
	if id != 1000<<22|513<<12|1 {
		t.Fatalf("id = %d，位布局不对", id)
	}
	if ms, w, seq := Decompose(id); ms != base || w != 513 || seq != 1 {
		t.Fatalf("Decompose = %d %d %d", ms, w, seq)
	}
}

func TestSequenceOverflow(t *testing.T) {
	calls := int64(0)
	base := epoch + 50
	s, _ := New(1, func() int64 { calls++; return base + calls/5000 })
	var id int64
	for i := 0; i < 4097; i++ {
		id, _ = s.Next()
	}
	if ms, _, seq := Decompose(id); ms != base+1 || seq != 0 {
		t.Fatalf("同一毫秒序列号用完后应等到下一毫秒：ms=%d seq=%d", ms-base, seq)
	}
}

func TestClockBackwards(t *testing.T) {
	vals := []int64{1000, 998, 999, 1000, 1001, 900}
	i := 0
	s, _ := New(1, func() int64 { v := vals[min(i, len(vals)-1)]; i++; return epoch + v })
	first, _ := s.Next()
	second, err := s.Next() // 回拨 2ms：等待追上
	if err != nil || second <= first {
		t.Fatalf("小幅回拨应等待：err=%v", err)
	}
	s.Next()
	if _, err := s.Next(); !errors.Is(err, ErrClockBackwards) {
		t.Fatalf("回拨 100ms 应返回 ErrClockBackwards，实际 %v", err)
	}
	if _, err := New(1024, nil); err == nil {
		t.Fatal("机器 ID 超出 10 位应返回错误")
	}
}

