package main

import "time"

func Series(avail ...float64) float64 {
	p := 1.0
	for _, a := range avail {
		p *= a
	}
	return p
}

func Parallel(avail ...float64) float64 {
	fail := 1.0
	for _, a := range avail {
		fail *= 1 - a
	}
	return 1 - fail
}

func Downtime(avail float64) time.Duration {
	year := 365 * 24 * time.Hour
	return time.Duration((1 - avail) * float64(year))
}

