		fn(key)
	}
}

type Node struct {
	l1  *Store
	l2  *Store
	db  *Store
	bus *Bus
}

func NewNode(l2, db *Store, bus *Bus) *Node {
	n := &Node{l1: NewStore(), l2: l2, db: db, bus: bus}
	bus.Subscribe(func(key string) { n.l1.Del(key) })
	return n
}

func (n *Node) Get(key string) (string, bool) {
	if v, ok := n.l1.Get(key); ok {
		return v, true
	}
	if v, ok := n.l2.Get(key); ok {
		n.l1.Set(key, v)
		return v, true
	}
	v, ok := n.db.Get(key)
	if ok {
		n.l2.Set(key, v)
		n.l1.Set(key, v)
	}
	return v, ok
}

func (n *Node) Update(key, val string) {
	n.db.Set(key, val)
	n.l2.Del(key)
	n.bus.Publish(key)
}

