package main

import "slices"

func AdvanceCommit(matchIndex []int, logTerms []int, currentTerm, commitIndex int) int {
	sorted := slices.Clone(matchIndex)
	slices.Sort(sorted)
	// 升序排序后，下标 (n-1)/2 处的值，就是至少多数节点都已达到的最大日志下标
	majority := sorted[(len(sorted)-1)/2]
	for n := majority; n > commitIndex; n-- {
		if logTerms[n-1] == currentTerm {
			return n
		}
	}
	return commitIndex
}

