package main

import (
	"hash/crc32"
	"slices"
	"strconv"
)

type Ring struct {
	replicas int
	hashes   []uint32
	owner    map[uint32]string
}

func NewRing(replicas int) *Ring {
	return &Ring{replicas: replicas, owner: map[uint32]string{}}
}

func (r *Ring) Add(nodes ...string) {
	for _, n := range nodes {
		for i := 0; i < r.replicas; i++ {
			h := crc32.ChecksumIEEE([]byte(n + "#" + strconv.Itoa(i)))
			if _, exists := r.owner[h]; !exists {
				r.hashes = append(r.hashes, h)
			}
			r.owner[h] = n
		}
	}
	slices.Sort(r.hashes)
}

func (r *Ring) Remove(node string) {
	r.hashes = slices.DeleteFunc(r.hashes, func(h uint32) bool {
		if r.owner[h] == node {
			delete(r.owner, h)
			return true
		}
		return false
	})
}

func (r *Ring) Get(key string) string {
	if len(r.hashes) == 0 {
		return ""
	}
	h := crc32.ChecksumIEEE([]byte(key))
	i, _ := slices.BinarySearch(r.hashes, h)
	if i == len(r.hashes) {
		i = 0
	}
	return r.owner[r.hashes[i]]
}

