package main

import (
	"errors"
	"sync"
	"sync/atomic"
)

var (
	ErrSoldOut   = errors.New("sold out")
	ErrDuplicate = errors.New("already purchased")
)

type Seckill struct {
	stock  atomic.Int64
	bought sync.Map
}

func NewSeckill(stock int64) *Seckill {
	s := &Seckill{}
	s.stock.Store(stock)
	return s
}

func (s *Seckill) Remaining() int64 { return s.stock.Load() }

func (s *Seckill) Buy(user string) error {
	if _, loaded := s.bought.LoadOrStore(user, true); loaded {
		return ErrDuplicate
	}
	for {
		cur := s.stock.Load()
		if cur <= 0 {
			s.bought.Delete(user)
