package main

import (
	"errors"
	"net/http"
	"net/url"
	"sync"
)

const alphabet = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

func Encode(id uint64) string {
	if id == 0 {
		return "0"
	}
	var buf [11]byte
	i := len(buf)
	for id > 0 {
		i--
		buf[i] = alphabet[id%62]
		id /= 62
	}
	return string(buf[i:])
}

type Shortener struct {
	mu     sync.RWMutex
	nextID uint64
	byCode map[string]string
	byURL  map[string]string
}

func NewShortener() *Shortener {
	return &Shortener{byCode: map[string]string{}, byURL: map[string]string{}}
}

func (s *Shortener) Shorten(rawURL string) (string, error) {
	u, err := url.Parse(rawURL)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
		return "", errors.New("invalid url")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if code, ok := s.byURL[rawURL]; ok {
		return code, nil
	}
	s.nextID++
	code := Encode(s.nextID)
	s.byCode[code] = rawURL
	s.byURL[rawURL] = code
	return code, nil
}

func (s *Shortener) Resolve(code string) (string, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	u, ok := s.byCode[code]
	return u, ok
}

func (s *Shortener) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /{code}", func(w http.ResponseWriter, r *http.Request) {
		target, ok := s.Resolve(r.PathValue("code"))
		if !ok {
			http.NotFound(w, r)
			return
		}
		http.Redirect(w, r, target, http.StatusFound)
	})
	return mux
}

