package main

import (
	"errors"
	"slices"
)

var (
	ErrInvalidTransition = errors.New("invalid status transition")
	ErrAmountMismatch    = errors.New("amount mismatch")
)

type Status string

var allowed = map[Status][]Status{
	"UNPAID":  {"PAID", "CANCELLED"},
	"PAID":    {"SHIPPED", "REFUNDED"},
	"SHIPPED": {"DONE"},
}

type Order struct {
	Status  Status
	Amount  int64
	PaidTxn string
}

func (o *Order) Transition(to Status) error {
	if !slices.Contains(allowed[o.Status], to) {
		return ErrInvalidTransition
	}
	o.Status = to
	return nil
}

func (o *Order) OnPaymentCallback(txn string, amount int64) error {
	if amount != o.Amount {
		return ErrAmountMismatch
	}
	if o.PaidTxn == txn {
		return nil
	}
	if err := o.Transition("PAID"); err != nil {
		return err
	}
	o.PaidTxn = txn
	return nil
}

