package main

import "sync"

type userState struct {
	personalUnread     int
	lastAckBroadcastID int64
}

type InboxService struct {
	mu         sync.RWMutex
	users      map[string]*userState
	broadcasts []int64
}

func NewInboxService() *InboxService {
	return &InboxService{users: make(map[string]*userState)}
}

func (s *InboxService) SendPersonal(userID string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	u := s.getOrCreateUser(userID)
	u.personalUnread++
}

func (s *InboxService) PublishBroadcast(broadcastID int64) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.broadcasts = append(s.broadcasts, broadcastID)
}

func (s *InboxService) CountUnread(userID string) int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var personal int
	var lastAck int64
	if u, ok := s.users[userID]; ok {
		personal = u.personalUnread
		lastAck = u.lastAckBroadcastID
	}
	unreadBroadcasts := 0
	for _, id := range s.broadcasts {
		if id > lastAck {
			unreadBroadcasts++
		}
	}
	return personal + unreadBroadcasts
}

func (s *InboxService) MarkAllRead(userID string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	u := s.getOrCreateUser(userID)
	u.personalUnread = 0
	if len(s.broadcasts) > 0 {
		u.lastAckBroadcastID = s.broadcasts[len(s.broadcasts)-1]
	}
}

func (s *InboxService) getOrCreateUser(userID string) *userState {
	u, ok := s.users[userID]
	if !ok {
		u = &userState{}
		s.users[userID] = u
	}
	return u
}

