package main

import (
	"context"
	"errors"
	"runtime"
	"testing"
	"time"
)

func slow(cost time.Duration) func(context.Context) string {
	return func(ctx context.Context) string {
		select {
		case <-time.After(cost):
			return "result"
		case <-ctx.Done():
			return ""
		}
	}
}

func waitGoroutines(t *testing.T, before int) {
	t.Helper()
	deadline := time.Now().Add(time.Second)
	for runtime.NumGoroutine() > before && time.Now().Before(deadline) {
		time.Sleep(5 * time.Millisecond)
	}
	if n := runtime.NumGoroutine(); n > before {
		t.Fatalf("goroutine 泄漏：之前 %d 个，现在 %d 个", before, n)
	}
}

func TestFast(t *testing.T) {
	if r, err := Query(context.Background(), slow(time.Millisecond), time.Second); err != nil || r != "result" {
		t.Fatalf("got %q, %v", r, err)
	}
}

func TestTimeoutNoLeak(t *testing.T) {
	before := runtime.NumGoroutine()
	for i := 0; i < 20; i++ {
		_, err := Query(context.Background(), slow(300*time.Millisecond), 10*time.Millisecond)
		if !errors.Is(err, context.DeadlineExceeded) {
			t.Fatalf("超时应返回 context.DeadlineExceeded，实际 %v", err)
		}
	}
	waitGoroutines(t, before)
}

func TestParentCancel(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	go func() { time.Sleep(10 * time.Millisecond); cancel() }()
	start := time.Now()
