package main

import (
	"context"
	"fmt"
	"sync"
)

func FetchAll(ctx context.Context, urls []string, limit int,
	fetch func(ctx context.Context, url string) (string, error)) ([]string, error) {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	results := make([]string, len(urls))
	sem := make(chan struct{}, limit)
	var (
		wg       sync.WaitGroup
		once     sync.Once
		firstErr error
	)
	for i, u := range urls {
		wg.Add(1)
		go func() {
			defer wg.Done()
			select {
			case sem <- struct{}{}:
			case <-ctx.Done():
				return
			}
			defer func() { <-sem }()
			body, err := fetch(ctx, u)
			if err != nil {
				once.Do(func() {
					firstErr = fmt.Errorf("fetch %s: %w", u, err)
					cancel()
				})
				return
			}
			results[i] = body
		}()
	}
	wg.Wait()
	if firstErr != nil {
		return nil, firstErr
	}
	return results, nil
}

