import "sync"

func Alternate(n int, odd, even func(int)) {
	oddTurn := make(chan struct{})
	evenTurn := make(chan struct{})
	var wg sync.WaitGroup
	wg.Add(2)
	go func() {
		defer wg.Done()
		for i := 1; i <= n; i += 2 {
			<-oddTurn
			odd(i)
			if i+1 <= n {
				evenTurn <- struct{}{}
			}
		}
	}()
	go func() {
		defer wg.Done()
		for i := 2; i <= n; i += 2 {
			<-evenTurn
			even(i)
			if i+1 <= n {
				oddTurn <- struct{}{}
			}
		}
	}()
	if n >= 1 {
		oddTurn <- struct{}{}
	}
	wg.Wait()
}

