package main

import (
	"context"
	"sync"
)

func Run(ctx context.Context, producers, consumers int,
	produce func(ctx context.Context) (int, bool), consume func(int)) {
	jobs := make(chan int, 16)
	var prod, cons sync.WaitGroup
	for p := 0; p < producers; p++ {
		prod.Add(1)
		go func() {
			defer prod.Done()
			for {
				job, ok := produce(ctx)
				if !ok {
					return
				}
				select {
				case jobs <- job:
				case <-ctx.Done():
					return
				}
			}
		}()
	}
	go func() {
		prod.Wait()
		close(jobs)
	}()
	for c := 0; c < consumers; c++ {
		cons.Add(1)
		go func() {
			defer cons.Done()
			for job := range jobs {
				consume(job)
			}
		}()
	}
	cons.Wait()
}

