package main

import (
	"sync"
	"time"
)

type item struct {
	val    string
	expire time.Time
}

type TTLCache struct {
	mu   sync.Mutex
	data map[string]item
	now  func() time.Time
	stop chan struct{}
	once sync.Once
	done chan struct{}
}

func NewTTLCache(interval time.Duration, now func() time.Time) *TTLCache {
	c := &TTLCache{data: map[string]item{}, now: now, stop: make(chan struct{}), done: make(chan struct{})}
	go func() {
		defer close(c.done)
		t := time.NewTicker(interval)
		defer t.Stop()
		for {
			select {
			case <-t.C:
				c.cleanup()
			case <-c.stop:
				return
			}
		}
	}()
	return c
}

func (c *TTLCache) cleanup() {
	c.mu.Lock()
	defer c.mu.Unlock()
	now := c.now()
	for k, it := range c.data {
		if !now.Before(it.expire) {
			delete(c.data, k)
		}
	}
}

func (c *TTLCache) Set(key, val string, ttl time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.data[key] = item{val, c.now().Add(ttl)}
}

func (c *TTLCache) Get(key string) (string, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	it, ok := c.data[key]
	if !ok {
		return "", false
	}
	if !c.now().Before(it.expire) {
		delete(c.data, key)
		return "", false
	}
	return it.val, true
}

func (c *TTLCache) Stop() {
	c.once.Do(func() { close(c.stop) })
	<-c.done
}

func (c *TTLCache) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return len(c.data)
}

