package main

import (
	"context"
	"sync"
)

func FetchAll(parentCtx context.Context, ids []int, fn func(context.Context, int) (string, error)) ([]string, error) {
	ctx, cancel := context.WithCancel(parentCtx)
	defer cancel()

	results := make([]string, len(ids))
	var (
		wg       sync.WaitGroup
		once     sync.Once
		firstErr error
	)

	for i, id := range ids {
		wg.Add(1)
		go func(idx, itemID int) {
			defer wg.Done()
			val, err := fn(ctx, itemID)
			if err != nil {
				once.Do(func() {
					firstErr = err
					cancel()
				})
				return
			}
			results[idx] = val
		}(i, id)
	}

	wg.Wait()
	if firstErr != nil {
		return nil, firstErr
	}
	return results, nil
}

