import "sync"

func ParallelApply(nums []int, slow func(int) int) []int {
	res := make([]int, len(nums))
	var wg sync.WaitGroup
	for i, v := range nums {
		wg.Add(1)
		go func() {
			defer wg.Done()
			res[i] = slow(v)
		}()
	}
	wg.Wait()
	return res
}

