package main

import "sync"

type job struct {
	idx int
	val int
}

func MapConcurrent(in []int, workers int, f func(int) int) []int {
	out := make([]int, len(in))
	jobs := make(chan job)
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs {
				out[j.idx] = f(j.val)
			}
		}()
	}
	for i, v := range in {
		jobs <- job{i, v}
	}
	close(jobs)
	wg.Wait()
	return out
}

