package main

import (
	"sync"
	"sync/atomic"
)

func CountWords(words []string, workers int) map[string]int64 {
	var counts sync.Map
	var wg sync.WaitGroup
	chunk := (len(words) + workers - 1) / max(workers, 1)
	for start := 0; start < len(words); start += chunk {
		part := words[start:min(start+chunk, len(words))]
		wg.Add(1)
		go func() {
			defer wg.Done()
			for _, w := range part {
				v, ok := counts.Load(w)
				if !ok {
					v, _ = counts.LoadOrStore(w, new(atomic.Int64))
				}
				v.(*atomic.Int64).Add(1)
			}
		}()
	}
	wg.Wait()
	out := make(map[string]int64)
	counts.Range(func(k, v any) bool {
		out[k.(string)] = v.(*atomic.Int64).Load()
		return true
	})
	return out
}

