func Pipeline(producers, perProducer, consumers int) int64 {
	ch := make(chan int, 16)
	var total atomic.Int64
	var prod sync.WaitGroup
	for p := 0; p < producers; p++ {
		prod.Add(1)
		go func() {
			defer prod.Done()
			for i := 1; i <= perProducer; i++ {
				ch <- i
			}
		}()
	}
	go func() {
		prod.Wait()
		close(ch)
	}()

	var cons sync.WaitGroup
	for c := 0; c < consumers; c++ {
		cons.Add(1)
		go func() {
			defer cons.Done()
			for v := range ch {
				total.Add(int64(v))
			}
		}()
	}
	cons.Wait()
	return total.Load()
}

