package main

import "time"

func CollectUntilIdle(ch <-chan int, idle time.Duration) []int {
	var out []int
	timer := time.NewTimer(idle)
	defer timer.Stop()
	for {
		select {
		case v, ok := <-ch:
			if !ok {
				return out
			}
			out = append(out, v)
			timer.Reset(idle)
		case <-timer.C:
			return out
		}
	}
}

