conc-25.solution:
package main

import (
	"context"
	"slices"
	"sync"
)

type waiter struct {
	n     int64
	ready chan struct{}
}

type Weighted struct {
	mu      sync.Mutex
	size    int64
	cur     int64
	waiters []*waiter
}

func NewWeighted(size int64) *Weighted {
	return &Weighted{size: size}
}

func (w *Weighted) TryAcquire(n int64) bool {
	w.mu.Lock()
	defer w.mu.Unlock()
	if w.size-w.cur >= n && len(w.waiters) == 0 {
		w.cur += n
		return true
	}
	return false
}

func (w *Weighted) Acquire(ctx context.Context, n int64) error {
	w.mu.Lock()
	if w.size-w.cur >= n && len(w.waiters) == 0 {
		w.cur += n
		w.mu.Unlock()
		return nil
	}
	if n > w.size {
		w.mu.Unlock()
		<-ctx.Done()
		return ctx.Err()
	}
	wt := &waiter{n: n, ready: make(chan struct{})}
	w.waiters = append(w.waiters, wt)
	w.mu.Unlock()

	select {
	case <-wt.ready:
		return nil
	case <-ctx.Done():
		w.mu.Lock()
		defer w.mu.Unlock()
		select {
		case <-wt.ready:
			w.cur -= n
			w.notifyLocked()
			return ctx.Err()
		default:
			wasFront := len(w.waiters) > 0 && w.waiters[0] == wt
			w.waiters = slices.DeleteFunc(w.waiters, func(x *waiter) bool { return x == wt })
			if wasFront && w.size > w.cur {
				w.notifyLocked()
			}
			return ctx.Err()
		}
	}
}

func (w *Weighted) Release(n int64) {
	w.mu.Lock()
	defer w.mu.Unlock()
	w.cur -= n
	w.notifyLocked()
}

func (w *Weighted) notifyLocked() {
	for len(w.waiters) > 0 {
		head := w.waiters[0]
		if w.size-w.cur < head.n {
			break
		}
		w.cur += head.n
		w.waiters = w.waiters[1:]
		close(head.ready)
	}
}

