package main

func DrainByPriority(high, low <-chan int) []int {
	var out []int
	for high != nil || low != nil {
		// 第一层：优先非阻塞排空 high
		if high != nil {
			select {
			case v, ok := <-high:
				if !ok {
					high = nil
				} else {
					out = append(out, v)
				}
				continue
			default:
			}
		}
		// 第二层：high 暂无可读数据时，阻塞等待任一通道
		select {
		case v, ok := <-high:
			if !ok {
				high = nil
			} else {
				out = append(out, v)
			}
		case v, ok := <-low:
			if !ok {
				low = nil
			} else {
				out = append(out, v)
			}
		}
	}
	return out
}

