package main

import "sync"

type entry struct {
	mu   sync.Mutex
	refs int
}

type RowLocker struct {
	mu    sync.Mutex
	locks map[string]*entry
}

func NewRowLocker() *RowLocker { return &RowLocker{locks: map[string]*entry{}} }

func (l *RowLocker) Lock(key string) {
	l.mu.Lock()
	e, ok := l.locks[key]
	if !ok {
		e = &entry{}
		l.locks[key] = e
	}
	e.refs++
	l.mu.Unlock()
	e.mu.Lock() // 在全局锁之外等待，不阻塞其他 key
}

func (l *RowLocker) Unlock(key string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	e := l.locks[key]
	e.refs--
	if e.refs == 0 {
		delete(l.locks, key)
	}
	e.mu.Unlock()
}

func (l *RowLocker) Size() int {
	l.mu.Lock()
	defer l.mu.Unlock()
	return len(l.locks)
}

