package main

import "slices"

type ReadView struct {
	Active       []int
	MinTrxID     int
	MaxTrxID     int
	CreatorTrxID int
}

type Version struct {
	TrxID int
	Value string
}

func NewReadView(active []int, nextTrxID, creator int) ReadView {
	v := ReadView{Active: slices.Clone(active), MinTrxID: nextTrxID, MaxTrxID: nextTrxID, CreatorTrxID: creator}
	if len(active) > 0 {
		v.MinTrxID = slices.Min(active)
	}
	return v
}

func (v ReadView) Visible(trxID int) bool {
	switch {
	case trxID == v.CreatorTrxID:
		return true
	case trxID < v.MinTrxID:
		return true
	case trxID >= v.MaxTrxID:
		return false
	default:
		return !slices.Contains(v.Active, trxID)
	}
}

func (v ReadView) Read(chain []Version) (string, bool) {
	for _, ver := range chain {
		if v.Visible(ver.TrxID) {
			return ver.Value, true
		}
	}
	return "", false
}

