package main

import "time"

type Replica struct {
	Name string
	Lag  time.Duration
}

type Router struct {
	now       func() time.Time
	window    time.Duration
	maxLag    time.Duration
	replicas  []Replica
	lastWrite map[string]time.Time
	next      int
}

func NewRouter(now func() time.Time, window, maxLag time.Duration, replicas []Replica) *Router {
	return &Router{now: now, window: window, maxLag: maxLag, replicas: replicas, lastWrite: map[string]time.Time{}}
}

func (r *Router) RecordWrite(user string) {
	r.lastWrite[user] = r.now()
}

func (r *Router) ReadTarget(user string) string {
	if t, ok := r.lastWrite[user]; ok && r.now().Sub(t) < r.window {
		return "primary"
	}
	for range r.replicas {
		rep := r.replicas[r.next%len(r.replicas)]
		r.next++
		if rep.Lag <= r.maxLag {
			return rep.Name
		}
	}
	return "primary"
}

