package main

import (
	"maps"
	"slices"
	"sync"
)

type Counter struct {
	mu      sync.Mutex
	pending map[string]int64
}

func NewCounter() *Counter { return &Counter{pending: map[string]int64{}} }

func (c *Counter) Add(key string, delta int64) {
	c.mu.Lock()
	c.pending[key] += delta
	c.mu.Unlock()
}

func (c *Counter) Flush(store func(key string, delta int64)) {
	c.mu.Lock()
	batch := c.pending
	c.pending = map[string]int64{}
	c.mu.Unlock()
	for _, k := range slices.Sorted(maps.Keys(batch)) {
		if d := batch[k]; d != 0 {
			store(k, d)
		}
	}
}

