		t.Fatalf("增量 = %v", got)
	}
	calls = nil
	c.Flush(func(k string, d int64) { calls = append(calls, k) })
	if len(calls) != 0 {
		t.Fatal("Flush 之后缓冲应清空")
	}
}

func TestFlushDoesNotBlockAdd(t *testing.T) {
	c := NewCounter()
	c.Add("a", 1)
	c.Flush(func(string, int64) {
		c.Add("b", 1) // store 期间调用 Add 不能死锁
	})
	var got int64
	c.Flush(func(k string, d int64) { got = d })
	if got != 1 {
		t.Fatal("store 期间的 Add 应被下一次 Flush 写出")
	}
}

