package main

import (
	"cmp"
	"slices"
)

type Entry struct {
	Member string
	Score  float64
}

type Leaderboard struct {
	scores map[string]float64
}

func NewLeaderboard() *Leaderboard { return &Leaderboard{scores: map[string]float64{}} }

func (l *Leaderboard) Add(member string, score float64) { l.scores[member] = score }

func (l *Leaderboard) IncrBy(member string, delta float64) float64 {
	l.scores[member] += delta
	return l.scores[member]
}

func (l *Leaderboard) sorted() []Entry {
	out := make([]Entry, 0, len(l.scores))
	for m, s := range l.scores {
		out = append(out, Entry{m, s})
	}
	slices.SortFunc(out, func(a, b Entry) int {
		return cmp.Or(cmp.Compare(b.Score, a.Score), cmp.Compare(a.Member, b.Member))
	})
	return out
}

func (l *Leaderboard) Rank(member string) (int, bool) {
	if _, ok := l.scores[member]; !ok {
		return 0, false
	}
	return slices.IndexFunc(l.sorted(), func(e Entry) bool { return e.Member == member }), true
}

func (l *Leaderboard) Top(n int) []Entry {
	s := l.sorted()
	return s[:min(n, len(s))]
}

