package main

type command struct {
	op    string
	key   string
	by    int
	reply chan int
}

type Server struct {
	cmds chan command
	done chan struct{}
	data map[string]int
}

func NewServer() *Server {
	s := &Server{cmds: make(chan command), done: make(chan struct{}), data: map[string]int{}}
	go s.loop()
	return s
}

func (s *Server) loop() {
	defer close(s.done)
	for c := range s.cmds {
		switch c.op {
		case "incr":
			s.data[c.key] += c.by
		}
		c.reply <- s.data[c.key]
	}
}

func (s *Server) Incr(key string, by int) int {
	reply := make(chan int, 1)
	s.cmds <- command{op: "incr", key: key, by: by, reply: reply}
	return <-reply
}

func (s *Server) Get(key string) int {
	reply := make(chan int, 1)
	s.cmds <- command{op: "get", key: key, reply: reply}
	return <-reply
}

func (s *Server) Close() {
	close(s.cmds)
	<-s.done
}

