package main

import (
	"maps"
	"slices"
)

type Cmd struct {
	Op  string // SET / INCR / DEL
	Key string
	Val int
}

func Replay(log []Cmd) map[string]int {
	data := map[string]int{}
	for _, c := range log {
		switch c.Op {
		case "SET":
			data[c.Key] = c.Val
		case "INCR":
			data[c.Key]++
		case "DEL":
			delete(data, c.Key)
		}
	}
	return data
}

func Rewrite(log []Cmd) []Cmd {
	data := Replay(log)
	out := make([]Cmd, 0, len(data))
	for _, k := range slices.Sorted(maps.Keys(data)) {
		out = append(out, Cmd{"SET", k, data[k]})
	}
	return out
}

