func TestDBRouterComprehensive(t *testing.T) {
	r := NewDBRouter("master", []string{"rep-1", "rep-2", "rep-3"}, 3*time.Second)
	bg := context.Background()

	// 1. 普通 SELECT 在健康从库间轮询负载均衡
	got := []string{
		r.RouteSQL(bg, "SELECT id, name FROM users WHERE id = 1"),
		r.RouteSQL(bg, "  select * from orders where user_id = 9 "),
		r.RouteSQL(bg, "SELECT count(*) FROM items"),
		r.RouteSQL(bg, "SELECT 1"),
	}
	want := []string{"rep-1", "rep-2", "rep-3", "rep-1"}
	if !slices.Equal(got, want) {
		t.Fatalf("normal SELECT round-robin = %v, want %v", got, want)
	}

	// 2. DML 写操作与 SELECT ... FOR UPDATE / LOCK IN SHARE MODE 必须强制走主库
	for _, q := range []string{
		"INSERT INTO orders VALUES (1)",
		"UPDATE users SET balance = 100 WHERE id = 1",
		"DELETE FROM sessions WHERE expired = 1",
		"SELECT balance FROM accounts WHERE id = 1 FOR UPDATE",
		"SELECT * FROM inventory WHERE sku = 99 LOCK IN SHARE MODE",
	} {
		if node := r.RouteSQL(bg, q); node != "master" {
			t.Fatalf("query %q routed to %q, want master", q, node)
		}
	}

	// 3. 事务上下文 WithTx 与强制主库标记 WithPrimary 必须走主库
	if node := r.RouteSQL(WithTx(bg), "SELECT * FROM users WHERE id = 1"); node != "master" {
		t.Fatalf("SELECT inside transaction routed to %q, want master", node)
	}
	if node := r.RouteSQL(WithPrimary(bg), "SELECT * FROM users WHERE id = 1"); node != "master" {
		t.Fatalf("SELECT with WithPrimary routed to %q, want master", node)
	}

	// 4. 从库 rep-2 复制延迟飙升至 10s (> 3s)，自动熔断摘除，只在 rep-1 和 rep-3 间轮询
	r.UpdateReplicaLag("rep-2", 10*time.Second)
	healthyGot := []string{
		r.RouteSQL(bg, "SELECT * FROM products"),
		r.RouteSQL(bg, "SELECT * FROM products"),
	}
	if !slices.Equal(healthyGot, []string{"rep-1", "rep-3"}) {
		t.Fatalf("after rep-2 lag spike, got %v, want [rep-1 rep-3]", healthyGot)
	}

	// 5. 所有从库延迟均超阈值时，自动熔断回退到主库 master
	r.UpdateReplicaLag("rep-1", 5*time.Second)
	r.UpdateReplicaLag("rep-3", 6*time.Second)
	if node := r.RouteSQL(bg, "SELECT * FROM products"); node != "master" {
		t.Fatalf("when all replicas lag, got %q, want master", node)
	}

	// 6. rep-2 追平延迟后自动恢复挂载
	r.UpdateReplicaLag("rep-2", 200*time.Millisecond)
	if node := r.RouteSQL(bg, "SELECT * FROM products"); node != "rep-2" {
		t.Fatalf("when rep-2 recovers, got %q, want rep-2", node)
	}

	// 7. 并发读写延迟水位与路由决策（配合 -race 检测锁保护）
	var wg sync.WaitGroup
	for i := range 16 {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for j := range 50 {
				r.UpdateReplicaLag("rep-1", time.Duration(j%5)*time.Second)
				_ = r.RouteSQL(bg, "SELECT id FROM users")
			}
		}(i)
	}
	wg.Wait()
}

