package main

import (
	"slices"
	"time"
)

type PelEntry struct {
	ID          string
	Consumer    string
	DeliveredAt time.Time
	Count       int
}

type ConsumerGroup struct {
	pel map[string]*PelEntry
}

func NewConsumerGroup() *ConsumerGroup {
	return &ConsumerGroup{pel: make(map[string]*PelEntry)}
}

func (g *ConsumerGroup) Deliver(id, consumer string, now time.Time) {
	g.pel[id] = &PelEntry{
		ID:          id,
		Consumer:    consumer,
		DeliveredAt: now,
		Count:       1,
	}
}

func (g *ConsumerGroup) Ack(id string) bool {
	if _, ok := g.pel[id]; ok {
		delete(g.pel, id)
		return true
	}
	return false
}

func (g *ConsumerGroup) AutoClaim(newConsumer string, minIdle time.Duration, now time.Time) []string {
	var claimed []string
	for id, e := range g.pel {
		if now.Sub(e.DeliveredAt) >= minIdle {
			e.Consumer = newConsumer
			e.DeliveredAt = now
			e.Count++
			claimed = append(claimed, id)
		}
	}
	slices.Sort(claimed)
	return claimed
}

