package main

func NextCap(oldCap, needed int) int {
	doubleCap := oldCap * 2
	if needed > doubleCap {
		return needed
	}
	const threshold = 256
	if oldCap < threshold {
		return doubleCap
	}
	newCap := oldCap
	for newCap < needed {
		newCap += (newCap + 3*threshold) / 4
	}
	return newCap
}

