go-34.solution:
package main

func EllipsisRunes(s string, maxRunes int) string {
	if maxRunes <= 0 {
		if s == "" {
			return ""
		}
		return "..."
	}
	count := 0
	for i := range s {
		if count == maxRunes {
			return s[:i] + "..."
		}
		count++
	}
	return s
}

