package main

type Permission uint8

const (
	PermRead Permission = 1 << iota
	PermWrite
	PermExec
)

func (cur Permission) Grant(p Permission) Permission {
	return cur | p
}

func (cur Permission) Revoke(p Permission) Permission {
	return cur &^ p
}

func (cur Permission) HasAll(p Permission) bool {
	return cur&p == p
}

