net-02.solution:
package main

type Packet struct {
	Seq  int
	Data string
}

func Reassemble(pkts []Packet) (data string, missing []int) {
	got := map[int]string{}
	maxSeq := -1
	for _, p := range pkts {
		if _, dup := got[p.Seq]; !dup {
			got[p.Seq] = p.Data
		}
		maxSeq = max(maxSeq, p.Seq)
	}
	contiguous := true
	for seq := 0; seq <= maxSeq; seq++ {
		d, ok := got[seq]
		if !ok {
			contiguous = false
			missing = append(missing, seq)
			continue
		}
		if contiguous {
			data += d
		}
	}
	return data, missing
}

