package main

import "time"

func HTTP1Time(costs []time.Duration, conns int) time.Duration {
	free := make([]time.Duration, conns) // 每个连接的空闲时刻
	var end time.Duration
	for _, c := range costs {
		i := 0
		for j := range free {
			if free[j] < free[i] {
				i = j
			}
		}
		free[i] += c
		end = max(end, free[i])
	}
	return end
}

func HTTP2Time(costs []time.Duration) time.Duration {
	var m time.Duration
	for _, c := range costs {
		m = max(m, c)
	}
	return m
}

