package main

import (
	"slices"
	"sync"
	"time"
)

type Monitor struct {
	mu   sync.Mutex
	last map[string]time.Time
}

func NewMonitor() *Monitor { return &Monitor{last: map[string]time.Time{}} }

func (m *Monitor) Beat(id string, now time.Time) {
	m.mu.Lock()
	m.last[id] = now
	m.mu.Unlock()
}

func (m *Monitor) Expired(now time.Time, timeout time.Duration) []string {
	m.mu.Lock()
	defer m.mu.Unlock()
	var out []string
	for id, t := range m.last {
		if now.Sub(t) > timeout {
			out = append(out, id)
			delete(m.last, id)
		}
	}
	slices.Sort(out)
	return out
}

func (m *Monitor) Len() int {
	m.mu.Lock()
	defer m.mu.Unlock()
	return len(m.last)
}

