package main

import (
	"errors"
	"io"
)

func Factorize(n int, send func(int) error) error {
	for p := 2; p*p <= n; p++ {
		for n%p == 0 {
			if err := send(p); err != nil {
				return err
			}
			n /= p
		}
	}
	if n > 1 {
		return send(n)
	}
	return nil
}

func SumStream(recv func() (int, error)) (int, error) {
	sum := 0
	for {
		v, err := recv()
		if errors.Is(err, io.EOF) {
			return sum, nil
		}
		if err != nil {
			return 0, err
		}
		sum += v
	}
}

func Doubler(recv func() (int, error), send func(int) error) error {
	for {
		v, err := recv()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		if err := send(v * 2); err != nil {
			return err
		}
	}
}

