package main

import (
	"errors"
	"sync"
	"sync/atomic"
)

var ErrNoAddr = errors.New("no healthy address")

type Picker struct {
	mu      sync.RWMutex
	addrs   []string
	healthy map[string]bool
	ready   []string // 健康地址的缓存
	next    atomic.Uint64
}

func NewPicker() *Picker { return &Picker{healthy: map[string]bool{}} }

func (p *Picker) rebuild() {
	p.ready = p.ready[:0:0]
	for _, a := range p.addrs {
		if p.healthy[a] {
			p.ready = append(p.ready, a)
		}
	}
}

func (p *Picker) Update(addrs []string) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.addrs = append([]string(nil), addrs...)
	p.healthy = map[string]bool{}
	for _, a := range addrs {
		p.healthy[a] = true
	}
	p.rebuild()
}

func (p *Picker) SetHealthy(addr string, ok bool) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if _, known := p.healthy[addr]; known {
		p.healthy[addr] = ok
		p.rebuild()
	}
}

func (p *Picker) Pick() (string, error) {
	p.mu.RLock()
	defer p.mu.RUnlock()
	if len(p.ready) == 0 {
		return "", ErrNoAddr
	}
	n := p.next.Add(1) - 1
	return p.ready[n%uint64(len(p.ready))], nil
}

