package main

import "slices"

type Wheel struct {
	slots []map[string]struct{}
	pos   int
	where map[string]int
}

func NewWheel(size int) *Wheel {
	w := &Wheel{slots: make([]map[string]struct{}, size), where: map[string]int{}}
	for i := range w.slots {
		w.slots[i] = map[string]struct{}{}
	}
	return w
}

func (w *Wheel) Add(id string, delay int) {
	w.Remove(id)
	slot := (w.pos + delay) % len(w.slots)
	w.slots[slot][id] = struct{}{}
	w.where[id] = slot
}

func (w *Wheel) Remove(id string) {
	if slot, ok := w.where[id]; ok {
		delete(w.slots[slot], id)
		delete(w.where, id)
	}
}

func (w *Wheel) Tick() []string {
	w.pos = (w.pos + 1) % len(w.slots)
	var out []string
	for id := range w.slots[w.pos] {
		out = append(out, id)
		delete(w.where, id)
	}
	w.slots[w.pos] = map[string]struct{}{}
	slices.Sort(out)
	return out
}

