package main

import "slices"

func RangeAssign(partitions int, consumers []string) map[string][]int {
	out := map[string][]int{}
	sorted := slices.Sorted(slices.Values(consumers))
	n := len(sorted)
	if n == 0 {
		return out
	}
	per, extra := partitions/n, partitions%n
	next := 0
	for i, c := range sorted {
		count := per
		if i < extra {
			count++
		}
		ps := []int{}
		for j := 0; j < count; j++ {
			ps = append(ps, next)
			next++
		}
		out[c] = ps
	}
	return out
}

