package main

import (
	"hash/fnv"
	"sync"
)

type KeyedMsg struct {
	Key string
	Seq int
}

func Partition(key string, n int) int {
	h := fnv.New32a()
	h.Write([]byte(key))
	return int(h.Sum32() % uint32(n))
}

func Dispatch(msgs []KeyedMsg, partitions int, handle func(KeyedMsg)) {
	queues := make([][]KeyedMsg, partitions)
	for _, m := range msgs {
		p := Partition(m.Key, partitions)
		queues[p] = append(queues[p], m)
	}
	var wg sync.WaitGroup
	for _, q := range queues {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for _, m := range q {
				handle(m)
			}
		}()
	}
	wg.Wait()
}

