package main

import (
	"crypto/tls"
	"errors"
	"strings"
	"sync/atomic"
)

type CertStore struct {
	cur atomic.Pointer[tls.Certificate]
}

func (s *CertStore) Update(c *tls.Certificate) {
	s.cur.Store(c)
}

func (s *CertStore) GetCertificate(_ *tls.ClientHelloInfo) (*tls.Certificate, error) {
	c := s.cur.Load()
	if c == nil {
		return nil, errors.New("no certificate loaded")
	}
	return c, nil
}

func VerifyClientSAN(cs tls.ConnectionState, allowedDNS []string) error {
	if len(cs.PeerCertificates) == 0 {
		return errors.New("missing peer certificate")
	}
	leaf := cs.PeerCertificates[0]
	for _, dns := range leaf.DNSNames {
		for _, allow := range allowedDNS {
			if strings.EqualFold(dns, allow) {
				return nil
			}
		}
	}
	return errors.New("client SAN not in allowlist")
}

