	for _, bad := range []string{"", "1 2 3", "1 2 3 4 5", "a 2 3 1/2 3"} {
		if _, err := ParseLoadAvg(bad); err == nil {
			t.Errorf("ParseLoadAvg(%q) 应返回错误", bad)
