package main

import (
	"fmt"
	"strings"
)

func CountFDs(output string) map[string]int {
	m := map[string]int{}
	for _, line := range strings.Split(output, "\n") {
		_, target, ok := strings.Cut(line, " -> ")
		if !ok {
			continue
		}
		switch {
		case strings.HasPrefix(target, "socket:"):
			m["socket"]++
		case strings.HasPrefix(target, "pipe:"):
			m["pipe"]++
		case strings.HasPrefix(target, "anon_inode:"):
			m["anon_inode"]++
		default:
			m["file"]++
		}
	}
	return m
}

func Check(counts map[string]int, limit int) string {
	total, top := 0, ""
	for k, v := range counts {
		total += v
		if top == "" || v > counts[top] || (v == counts[top] && k < top) {
			top = k
		}
	}
	pct := total * 100 / limit
	if pct <= 80 {
		return ""
	}
	return fmt.Sprintf("fd usage %d%% (mostly %s)", pct, top)
}

