func Classify(upstreamStatus string, duration, proxyTimeout time.Duration) string {
	switch {
	case upstreamStatus == "-" && duration >= proxyTimeout:
		return "504-timeout"
	case upstreamStatus == "-":
		return "502-reset"
	case strings.HasPrefix(upstreamStatus, "5"):
		return "upstream-5xx"
	}
	return "ok"
