perf-24.solution:
package main

import "time"

func Batch(in <-chan int, max int, wait time.Duration) <-chan []int {
	out := make(chan []int)
	go func() {
		defer close(out)
		var batch []int
		var timer *time.Timer
		var timeout <-chan time.Time
		flush := func() {
			if len(batch) > 0 {
				out <- batch
				batch = nil
			}
			if timer != nil {
				timer.Stop()
				timer, timeout = nil, nil
			}
		}
		for {
			select {
			case v, ok := <-in:
				if !ok {
					flush()
					return
				}
				if len(batch) == 0 {
					timer = time.NewTimer(wait)
					timeout = timer.C
				}
				batch = append(batch, v)
				if len(batch) >= max {
					flush()
				}
			case <-timeout:
				flush()
			}
		}
	}()
	return out
}

