package main

import (
	"errors"
	"strconv"
	"strings"
	"time"
)

func ParseCPUStat(text string) (map[string]int64, error) {
	m := map[string]int64{}
	for _, line := range strings.Split(strings.TrimSpace(text), "\n") {
		f := strings.Fields(line)
		if len(f) != 2 {
			return nil, errors.New("bad line: " + line)
		}
		v, err := strconv.ParseInt(f[1], 10, 64)
		if err != nil {
			return nil, err
		}
		m[f[0]] = v
	}
	return m, nil
}

func Throttle(a, b map[string]int64) (ratio float64, avg time.Duration) {
	periods := b["nr_periods"] - a["nr_periods"]
	throttled := b["nr_throttled"] - a["nr_throttled"]
	if periods <= 0 || throttled <= 0 {
		return 0, 0
	}
	usec := b["throttled_usec"] - a["throttled_usec"]
	return float64(throttled) / float64(periods), time.Duration(usec/throttled) * time.Microsecond
}

