	// 1. 插入两条连接填满表：c1 为 TIME_WAIT (TTL=30s)，c2 为 UNREPLIED (TTL=30s)
	if ok, r := tbl.Track("c1", "TIME_WAIT", 30, 100); !ok || r != "inserted" {
		t.Fatalf("c1 track = %v, %q", ok, r)
