	if ok, r := tbl.Track("c2", "UNREPLIED", 30, 100); !ok || r != "inserted" {
		t.Fatalf("c2 track = %v, %q", ok, r)
	}

	// 2. 已存在连接 c1 状态刷新，不占新槽位
	if ok, r := tbl.Track("c1", "TIME_WAIT", 20, 105); !ok || r != "updated" {
		t.Fatalf("c1 update = %v, %q", ok, r)
	}

	// 3. 在 t=110s（c1 过期时间为 125s，均未过期）插入新连接 c3 -> 触发 Early-Drop 踢掉 UNREPLIED 的 c2！
	if ok, r := tbl.Track("c3", "ESTABLISHED", 300, 110); !ok || r != "inserted" {
		t.Fatalf("c3 should succeed via early_drop of c2, got %v, %q", ok, r)
	}
	if tbl.EarlyDrops != 1 {
		t.Fatalf("EarlyDrops = %d, want 1", tbl.EarlyDrops)
	}

	// 4. 在 t=115s（c1=TIME_WAIT@125, c3=ESTABLISHED@410，无 UNREPLIED 也无过期）插入 c4 -> 触发 table_full 丢包！
	if ok, r := tbl.Track("c4", "ESTABLISHED", 300, 115); ok || r != "table_full" {
		t.Fatalf("c4 should fail with table_full, got %v, %q", ok, r)
	}
	if tbl.Drops != 1 {
		t.Fatalf("Drops = %d, want 1", tbl.Drops)
	}

	// 5. 到 t=130s 时，c1 (TIME_WAIT@125) 已过期，此时插入 c4 应清理过期 c1 后成功插入
	if ok, r := tbl.Track("c4", "ESTABLISHED", 300, 130); !ok || r != "inserted" {
		t.Fatalf("c4 at t=130 should evict expired c1 and succeed, got %v, %q", ok, r)
	}
}

