func TestComputeFlameStats(t *testing.T) {
	lines := []string{
		"main;Handler;Service;MarshalJSON 90",
		"main;Handler;Service 5",
		"main;Handler;Walk;Walk 10", // 递归调用 Walk;Walk
	}

	got := ComputeFlameStats(lines)

	// main 和 Handler 只是入口底座：Cum=105, Flat=0
	if got["Handler"] != (FlameStat{Flat: 0, Cum: 105}) {
		t.Fatalf("Handler = %+v, want {Flat:0 Cum:105}", got["Handler"])
	}
	// Service 自身作为栈顶 5 次，调用 MarshalJSON 90 次：Flat=5, Cum=95
	if got["Service"] != (FlameStat{Flat: 5, Cum: 95}) {
		t.Fatalf("Service = %+v, want {Flat:5 Cum:95}", got["Service"])
