package main

type P struct {
	ID        int
	RunNext   int
	Local     []int
	SchedTick int
}

type Sched struct {
	Global []int
	Ps     []*P
}

func FindRunnable(s *Sched, p *P) int {
	p.SchedTick++
	if p.SchedTick%61 == 0 && len(s.Global) > 0 {
		g := s.Global[0]
		s.Global = s.Global[1:]
		return g
	}
	if p.RunNext != 0 {
		g := p.RunNext
		p.RunNext = 0
		return g
	}
	if len(p.Local) > 0 {
		g := p.Local[0]
		p.Local = p.Local[1:]
		return g
	}
	if len(s.Global) > 0 {
		g := s.Global[0]
		s.Global = s.Global[1:]
		return g
	}
	for _, victim := range s.Ps {
		if victim == p || len(victim.Local) == 0 {
			continue
		}
		n := len(victim.Local) - len(victim.Local)/2
		stolen := victim.Local[:n:n]
		victim.Local = victim.Local[n:]
		p.Local = append(p.Local, stolen[1:]...)
		return stolen[0]
	}
	return 0
}

