package main

type Task struct {
	Name string
	Work int
}

type Finish struct {
	Name string
	At   int
}

func Schedule(tasks []Task, quantum int) []Finish {
	queue := append([]Task(nil), tasks...)
	var out []Finish
	now := 0
	for len(queue) > 0 {
		t := queue[0]
		queue = queue[1:]
		run := min(t.Work, quantum)
		now += run
		t.Work -= run
		if t.Work == 0 {
			out = append(out, Finish{t.Name, now})
		} else {
			queue = append(queue, t)
		}
	}
	return out
}

