package main

import "slices"

func Mark(heap map[int][]int, roots []int) map[int]bool {
	black := map[int]bool{}
	grey := map[int]bool{}
	var queue []int
	for _, r := range roots {
		if !grey[r] {
			grey[r] = true
			queue = append(queue, r)
		}
	}
	for len(queue) > 0 {
		x := queue[0]
		queue = queue[1:]
		for _, y := range heap[x] {
			if !grey[y] && !black[y] {
				grey[y] = true
				queue = append(queue, y)
			}
		}
		delete(grey, x)
		black[x] = true
	}
	return black
}

func Sweep(heap map[int][]int, marked map[int]bool) []int {
	var garbage []int
	for x := range heap {
		if !marked[x] {
			garbage = append(garbage, x)
		}
	}
	slices.Sort(garbage)
	return garbage
}

