func ParseGOGC(s string) (int, error) {
	switch s {
	case "":
		return 100, nil
	case "off":
		return -1, nil
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 0 {
		return 0, errors.New("invalid GOGC")
	}
	return n, nil
}

func HeapGoal(live, stacks, globals uint64, gogc int, memLimit uint64) uint64 {
	if gogc < 0 {
		if memLimit == 0 {
			return math.MaxUint64
		}
		return memLimit
	}
	goal := live + (live+stacks+globals)*uint64(gogc)/100
	if memLimit > 0 && goal > memLimit {
		return memLimit
	}
	return goal
}

