func RoundUp(size int) int {
	if size > 32768 {
		return (size + pageSize - 1) / pageSize * pageSize
	}
	i, _ := slices.BinarySearch(sizeClasses, size)
	return sizeClasses[i]
}

func Kind(size int, hasPointers bool) string {
	switch {
	case size < 16 && !hasPointers:
		return "tiny"
	case size <= 32768:
		return "small"
	default:
		return "large"
	}
}

