package main

import "runtime"

type MemStats struct {
	HeapInuse    uint64
	HeapIdle     uint64
	HeapReleased uint64
	StackInuse   uint64
	Sys          uint64
}

func Snapshot() MemStats {
	var ms runtime.MemStats
	runtime.ReadMemStats(&ms)
	return MemStats{
		HeapInuse:    ms.HeapInuse,
		HeapIdle:     ms.HeapIdle,
		HeapReleased: ms.HeapReleased,
		StackInuse:   ms.StackInuse,
		Sys:          ms.Sys,
	}
}

func Explain(rss uint64, m MemStats) []string {
	var out []string
	if m.HeapIdle-m.HeapReleased > rss/4 {
		out = append(out, "idle-not-released")
	}
	if m.StackInuse > rss/4 {
		out = append(out, "goroutine-stacks")
	}
	if float64(rss) > float64(m.Sys)*1.1 {
		out = append(out, "non-go-memory")
	}
	if len(out) == 0 && float64(m.HeapInuse) > float64(rss)*0.6 {
		out = append(out, "heap-in-use")
	}
	return out
}

