	p := NewBlockingPool(4)
	var running, maxRunning atomic.Int32
	var wg sync.WaitGroup
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			p.Do(context.Background(), func() {
				n := running.Add(1)
				for {
					m := maxRunning.Load()
					if n <= m || maxRunning.CompareAndSwap(m, n) {
						break
					}
				}
				time.Sleep(15 * time.Millisecond)
				running.Add(-1)
			})
		}()
	}
	wg.Wait()
	if m := maxRunning.Load(); m != 4 {
		t.Fatalf("最大并发 = %d，期望 4", m)
	}
}

func TestCancelWhileWaiting(t *testing.T) {
	p := NewBlockingPool(1)
	release := make(chan struct{})
	go p.Do(context.Background(), func() { <-release })
	time.Sleep(10 * time.Millisecond)

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	ran := false
	err := p.Do(ctx, func() { ran = true })
	close(release)
	if !errors.Is(err, context.DeadlineExceeded) || ran {
		t.Fatalf("排队超时应返回 DeadlineExceeded 且不执行 fn：err=%v ran=%v", err, ran)
