package main

type GStatus string

const (
	Grunnable GStatus = "_Grunnable"
	Grunning  GStatus = "_Grunning"
	Gwaiting  GStatus = "_Gwaiting"
)

type SimG struct {
	ID         int
	Status     GStatus
	WaitReason string
}

type MiniP struct {
	running *SimG
	runnext *SimG
	runq    []*SimG
}

func (p *MiniP) Schedule() *SimG {
	var next *SimG
	if p.runnext != nil {
		next = p.runnext
		p.runnext = nil
	} else if len(p.runq) > 0 {
		next = p.runq[0]
		p.runq = p.runq[1:]
	}
	if next == nil {
		p.running = nil
		return nil
	}
	next.Status = Grunning
	next.WaitReason = ""
	p.running = next
	return next
}

func (p *MiniP) GoPark(reason string) *SimG {
	if p.running == nil {
		return nil
	}
	cur := p.running
	cur.Status = Gwaiting
	cur.WaitReason = reason
	p.running = nil
	return p.Schedule()
}

func (p *MiniP) GoReady(g *SimG) {
	g.Status = Grunnable
	g.WaitReason = ""
	if p.runnext != nil {
		p.runq = append(p.runq, p.runnext)
	}
	p.runnext = g
	if p.running == nil {
		p.Schedule()
	}
}

