		t.Fatalf("after GoReady(g1): running=%v, status=%v, reason=%q", p.running, g1.Status, g1.WaitReason)
	}

	// 2. g1 运行期间先后唤醒 g2、g3：g2 先入 runnext，随后 g3 顶替 runnext 并把 g2 踢入 runq
	p.GoReady(g2)
	p.GoReady(g3)
	if p.runnext != g3 || g3.Status != Grunnable {
		t.Fatalf("expected g3 in runnext, got %v", p.runnext)
	}
	if len(p.runq) != 1 || p.runq[0] != g2 {
		t.Fatalf("expected g2 kicked to runq, got %v", p.runq)
	}

	// 3. g1 因 "chan receive" 调用 GoPark：g1 变为 _Gwaiting，且优先从 runnext 调度 g3 上核！
	next := p.GoPark("chan receive")
	if g1.Status != Gwaiting || g1.WaitReason != "chan receive" {
		t.Fatalf("g1 should be _Gwaiting(chan receive), got (%v, %q)", g1.Status, g1.WaitReason)
	}
	if next != g3 || p.running != g3 || g3.Status != Grunning {
		t.Fatalf("expected g3 scheduled from runnext, got %v", next)
	}

	// 4. g3 因 "IO wait" 调用 GoPark：从 runq 弹出 g2 上核
	next = p.GoPark("IO wait")
	if next != g2 || p.running != g2 || g2.Status != Grunning {
		t.Fatalf("expected g2 scheduled from runq, got %v", next)
	}

	// 5. g2 再次唤醒 g1 后自身 GoPark：g1 从 runnext 立即接棒运行
	p.GoReady(g1)
	next = p.GoPark("semacquire")
	if next != g1 || g1.Status != Grunning || g1.WaitReason != "" {
		t.Fatalf("expected g1 re-scheduled with cleared WaitReason, got %+v", g1)
	}
}

