func mw(name string) HandlerFunc {
	return func(c *Context) {
		c.Log = append(c.Log, name+" before")
		c.Next()
		c.Log = append(c.Log, name+" after")
	}
}

func handler(c *Context) { c.Log = append(c.Log, "handler") }

func TestOnion(t *testing.T) {
	c := Run(mw("A"), mw("B"), handler)
	want := []string{"A before", "B before", "handler", "B after", "A after"}
	if !slices.Equal(c.Log, want) {
		t.Fatalf("Log = %v\n期望 %v", c.Log, want)
	}
}

func TestWithoutNext(t *testing.T) {
	plain := func(c *Context) { c.Log = append(c.Log, "plain") }
	c := Run(plain, mw("A"), handler)
	want := []string{"plain", "A before", "handler", "A after"}
	if !slices.Equal(c.Log, want) {
		t.Fatalf("Log = %v\n期望 %v（不调用 Next 的中间件返回后也要继续执行）", c.Log, want)
	}
}

func TestAbort(t *testing.T) {
	auth := func(c *Context) {
		c.Log = append(c.Log, "auth failed")
		c.Abort()
		c.Log = append(c.Log, "after abort") // Abort 不会中断当前函数
	}
	c := Run(mw("A"), auth, handler)
	want := []string{"A before", "auth failed", "after abort", "A after"}
	if !slices.Equal(c.Log, want) || !c.IsAborted() {
		t.Fatalf("Log = %v\n期望 %v", c.Log, want)
	}
}

