package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"strings"
	"time"
)

var (
	ErrMalformed = errors.New("malformed token")
	ErrSignature = errors.New("invalid signature")
	ErrExpired   = errors.New("token expired")
)

type Claims struct {
	Sub string `json:"sub"`
	Exp int64  `json:"exp"`
}

type header struct {
	Alg string `json:"alg"`
	Typ string `json:"typ"`
}

var enc = base64.RawURLEncoding

func sign(data string, secret []byte) []byte {
	mac := hmac.New(sha256.New, secret)
	mac.Write([]byte(data))
	return mac.Sum(nil)
}

func Sign(c Claims, secret []byte) (string, error) {
	h, _ := json.Marshal(header{"HS256", "JWT"})
	p, err := json.Marshal(c)
	if err != nil {
		return "", err
	}
	unsigned := enc.EncodeToString(h) + "." + enc.EncodeToString(p)
	return unsigned + "." + enc.EncodeToString(sign(unsigned, secret)), nil
}

func Verify(token string, secret []byte, now time.Time) (Claims, error) {
	var c Claims
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return c, ErrMalformed
	}
	hb, err1 := enc.DecodeString(parts[0])
	pb, err2 := enc.DecodeString(parts[1])
	sig, err3 := enc.DecodeString(parts[2])
	if err1 != nil || err2 != nil || err3 != nil {
		return c, ErrMalformed
	}
	var h header
	if json.Unmarshal(hb, &h) != nil || h.Alg != "HS256" {
		return c, ErrMalformed
	}
	if !hmac.Equal(sig, sign(parts[0]+"."+parts[1], secret)) {
		return c, ErrSignature
	}
	if json.Unmarshal(pb, &c) != nil {
		return Claims{}, ErrMalformed
	}
	if c.Exp <= now.Unix() {
		return c, ErrExpired
	}
	return c, nil
}

