	now := time.Unix(1700000000, 0)
	tok, _ := Sign(Claims{Sub: "alice", Exp: now.Add(time.Hour).Unix()}, secret)
	c, err := Verify(tok, secret, now)
	if err != nil || c.Sub != "alice" {
		t.Fatalf("Verify = %+v, %v", c, err)
	}
	if _, err := Verify(tok, []byte("wrong"), now); !errors.Is(err, ErrSignature) {
		t.Errorf("错误的密钥：%v", err)
	}
	if _, err := Verify(tok, secret, now.Add(2*time.Hour)); !errors.Is(err, ErrExpired) {
		t.Errorf("过期：%v", err)
	}
	parts := strings.Split(tok, ".")
	forged := base64.RawURLEncoding.EncodeToString([]byte(`{"sub":"admin","exp":9999999999}`))
	if _, err := Verify(parts[0]+"."+forged+"."+parts[2], secret, now); !errors.Is(err, ErrSignature) {
		t.Errorf("篡改 payload：%v", err)
	}
	none := base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"none","typ":"JWT"}`))
	if _, err := Verify(none+"."+parts[1]+".", secret, now); !errors.Is(err, ErrMalformed) {
		t.Errorf("alg=none：%v", err)
	}
	for _, bad := range []string{"", "a.b", "a.b.c.d", "!!.!!.!!"} {
		if _, err := Verify(bad, secret, now); !errors.Is(err, ErrMalformed) {
			t.Errorf("Verify(%q) = %v，期望 ErrMalformed", bad, err)
		}
	}
}

