package main

import "time"

type Revoker struct {
	now     func() time.Time
	revoked map[string]time.Time
}

func NewRevoker(now func() time.Time) *Revoker {
	return &Revoker{now: now, revoked: map[string]time.Time{}}
}

func (r *Revoker) Revoke(jti string, exp time.Time) {
	r.revoked[jti] = exp
}

func (r *Revoker) IsRevoked(jti string) bool {
	exp, ok := r.revoked[jti]
	return ok && r.now().Before(exp)
}

func (r *Revoker) Cleanup() int {
	n := 0
	now := r.now()
	for jti, exp := range r.revoked {
		if !now.Before(exp) {
			delete(r.revoked, jti)
			n++
		}
	}
	return n
}

