	rec, called := serve("GET", map[string]string{"Origin": "https://app.example.com"})
	if !called || rec.Header().Get("Access-Control-Allow-Origin") != "https://app.example.com" ||
		rec.Header().Get("Access-Control-Allow-Credentials") != "true" || rec.Header().Get("Vary") != "Origin" {
		t.Fatalf("called=%v headers=%v", called, rec.Header())
	}
}

func TestPreflight(t *testing.T) {
	rec, called := serve("OPTIONS", map[string]string{
		"Origin":                         "https://app.example.com",
		"Access-Control-Request-Method":  "PUT",
		"Access-Control-Request-Headers": "Content-Type, X-Token",
	})
	if called {
		t.Fatal("预检请求不应调用 next")
	}
	h := rec.Header()
	if rec.Code != 204 || h.Get("Access-Control-Allow-Methods") != "GET, POST, PUT, DELETE" ||
		h.Get("Access-Control-Allow-Headers") != "Content-Type, X-Token" || h.Get("Access-Control-Max-Age") != "600" {
		t.Fatalf("预检响应不对：%d %v", rec.Code, h)
	}
}

