	if !called || rec.Header().Get("Access-Control-Allow-Origin") != "" {
		t.Fatal("不在白名单的来源不应获得 CORS 头")
	}
	rec, called = serve("OPTIONS", map[string]string{"Origin": "https://evil.example", "Access-Control-Request-Method": "DELETE"})
	if called || rec.Code != 403 {
		t.Fatalf("不在白名单的预检应返回 403，实际 %d", rec.Code)
