package main

import (
	"sync"
	"time"
)

// window 是一个已经实现好的固定窗口计数器：每个窗口最多 limit 个请求。
type window struct {
	start time.Time
	count int
}

func (w *window) allow(now time.Time, limit int, size time.Duration) bool {
	if now.Sub(w.start) >= size {
		w.start, w.count = now, 0
	}
	if w.count >= limit {
		return false
	}
	w.count++
	return true
}

type keyState struct {
	w        window
	lastSeen time.Time
}

type KeyedLimiter struct {
	mu    sync.Mutex
	now   func() time.Time
	limit int
	size  time.Duration
	idle  time.Duration
	keys  map[string]*keyState
}

func NewKeyedLimiter(now func() time.Time, limit int, size, idle time.Duration) *KeyedLimiter {
	return &KeyedLimiter{now: now, limit: limit, size: size, idle: idle, keys: map[string]*keyState{}}
}

func (l *KeyedLimiter) Allow(key string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
	st, ok := l.keys[key]
	if !ok {
		st = &keyState{}
		l.keys[key] = st
	}
	st.lastSeen = now
	return st.w.allow(now, l.limit, l.size)
}

func (l *KeyedLimiter) Cleanup() int {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
	n := 0
	for k, st := range l.keys {
		if now.Sub(st.lastSeen) > l.idle {
			delete(l.keys, k)
			n++
		}
	}
	return n
}

func (l *KeyedLimiter) Len() int {
	l.mu.Lock()
	defer l.mu.Unlock()
	return len(l.keys)
}

