	ExistsByName(ctx context.Context, name string) (bool, error)
	Create(ctx context.Context, u *User) error
}

type UserService struct {
	repo UserRepo
	now  func() time.Time
}

func NewUserService(repo UserRepo, now func() time.Time) *UserService {
	return &UserService{repo: repo, now: now}
}

func (s *UserService) Register(ctx context.Context, name string) (*User, error) {
	name = strings.TrimSpace(name)
	if n := utf8.RuneCountInString(name); n < 2 || n > 20 {
		return nil, ErrInvalidName
	}
	exists, err := s.repo.ExistsByName(ctx, name)
	if err != nil {
		return nil, fmt.Errorf("check name: %w", err)
	}
	if exists {
		return nil, ErrDuplicate
	}
	u := &User{Name: name, CreatedAt: s.now()}
	if err := s.repo.Create(ctx, u); err != nil {
		return nil, fmt.Errorf("create user: %w", err)
	}
	return u, nil
}

