package main

type Pool struct {
	maxIdlePerHost int
	idle           map[string][]int
	nextID         int
	Dialed         int
	Closed         int
}

func NewPool(maxIdlePerHost int) *Pool {
	return &Pool{maxIdlePerHost: maxIdlePerHost, idle: map[string][]int{}}
}

func (p *Pool) Get(host string) int {
	if conns := p.idle[host]; len(conns) > 0 {
		c := conns[len(conns)-1]
		p.idle[host] = conns[:len(conns)-1]
		return c
	}
	p.nextID++
	p.Dialed++
	return p.nextID
}

func (p *Pool) Put(host string, conn int) {
	if len(p.idle[host]) >= p.maxIdlePerHost {
		p.Closed++
		return
	}
	p.idle[host] = append(p.idle[host], conn)
}

