func TestVerify(t *testing.T) {
	now := time.Unix(1760320800, 0)
	body := []byte(`{"event":"paid","order":"A1"}`)
	h := Sign(body, secret, now.Add(-30*time.Second))
	if err := Verify(body, h, secret, now, 5*time.Minute); err != nil {
		t.Fatalf("合法请求被拒绝：%v", err)
	}
	cases := []struct {
		name   string
		body   []byte
		header string
		secret []byte
		want   error
	}{
		{"篡改 body", []byte(`{"event":"paid","order":"A2"}`), h, secret, ErrSignature},
		{"错误的密钥", body, h, []byte("other"), ErrSignature},
		{"过旧", body, Sign(body, secret, now.Add(-10*time.Minute)), secret, ErrExpired},
		{"来自未来", body, Sign(body, secret, now.Add(10*time.Minute)), secret, ErrExpired},
		{"缺少签名", body, "t=1760320800", secret, ErrBadHeader},
		{"时间戳非法", body, "t=abc,v1=00", secret, ErrBadHeader},
		{"空头部", body, "", secret, ErrBadHeader},
	}
	for _, c := range cases {
		if err := Verify(c.body, c.header, c.secret, now, 5*time.Minute); !errors.Is(err, c.want) {
			t.Errorf("%s：Verify = %v，期望 %v", c.name, err, c.want)
		}
	}
}

