	newSig := Sign(body, secret, now)
	header := oldSig + "," + newSig[len("t=1760320800,"):]
	if err := Verify(body, header, secret, now, time.Minute); err != nil {
		t.Fatalf("多个 v1 中任意一个匹配即可：%v", err)
