package main

import (
	"encoding/json"
	"net/http"
	"strings"
)

type User struct {
	FirstName string
	LastName  string
}

func Version(r *http.Request) int {
	switch {
	case strings.HasPrefix(r.URL.Path, "/v2/"):
		return 2
	case strings.HasPrefix(r.URL.Path, "/v1/"):
		return 1
	case strings.Contains(r.Header.Get("Accept"), "application/vnd.shop.v2+json"):
		return 2
	}
	return 1
}

func RenderUser(version int, u User) ([]byte, error) {
	if version >= 2 {
		return json.Marshal(struct {
			FirstName string `json:"first_name"`
			LastName  string `json:"last_name"`
		}{u.FirstName, u.LastName})
	}
	return json.Marshal(struct {
		Name string `json:"name"`
	}{strings.TrimSpace(u.FirstName + " " + u.LastName)})
}

