package main

import (
	"context"
	"net/http"
	"sync"
	"sync/atomic"
)

type DrainCoordinator struct {
	draining atomic.Bool
	mu       sync.Mutex
	inflight int
	doneCh   chan struct{}
}

func NewDrainCoordinator() *DrainCoordinator {
	return &DrainCoordinator{doneCh: make(chan struct{})}
}

func (d *DrainCoordinator) ReadyHandler(w http.ResponseWriter, r *http.Request) {
	if d.draining.Load() {
		http.Error(w, "draining", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
}

func (d *DrainCoordinator) Wrap(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		d.mu.Lock()
		d.inflight++
		d.mu.Unlock()
		defer func() {
			d.mu.Lock()
			d.inflight--
			if d.draining.Load() && d.inflight == 0 {
				select {
				case <-d.doneCh:
				default:
					close(d.doneCh)
				}
			}
			d.mu.Unlock()
		}()
		next.ServeHTTP(w, r)
	})
}

func (d *DrainCoordinator) Drain(ctx context.Context) error {
	d.mu.Lock()
	d.draining.Store(true)
	if d.inflight == 0 {
		select {
		case <-d.doneCh:
		default:
			close(d.doneCh)
		}
	}
	d.mu.Unlock()

	select {
	case <-d.doneCh:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

