package main

import (
	"bytes"
	"log/slog"
	"strings"
	"testing"
	"time"
)

func TestLoginAuditLogValuer(t *testing.T) {
	var buf bytes.Buffer
	logger := slog.New(slog.NewJSONHandler(&buf, nil))
	audit := LoginAudit{User: "alice", Phone: "13812345678", Token: "secret-jwt-token"}
	logger.Info("login", "audit", audit)

	out := buf.String()
	if strings.Contains(out, "secret-jwt-token") || strings.Contains(out, "13812345678") {
		t.Fatalf("sensitive info leaked in log: %s", out)
	}
	if !strings.Contains(out, "138****5678") || !strings.Contains(out, "[REDACTED]") {
		t.Fatalf("expected masked phone and REDACTED token, got: %s", out)
	}
}

func TestLogSampler(t *testing.T) {
	sampler := NewLogSampler(time.Second, 3, 5)
	t0 := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)

	var allowed []int
	for i := 1; i <= 15; i++ {
		if sampler.Allow("db_timeout", t0.Add(10*time.Millisecond)) {
			allowed = append(allowed, i)
		}
	}
	// 前 3 次 (1, 2, 3) 放行，之后每 5 次放行 1 次 (8, 13)
	want := []int{1, 2, 3, 8, 13}
	if len(allowed) != len(want) {
		t.Fatalf("allowed = %v, want %v", allowed, want)
	}
	for i := range want {
		if allowed[i] != want[i] {
			t.Fatalf("allowed = %v, want %v", allowed, want)
		}
	}

	// 进入下一个 1s 窗口，计数器重置，第 1 次再次放行
	if !sampler.Allow("db_timeout", t0.Add(time.Second)) {
		t.Fatal("should allow again in new time window")
	}
}
